import java.util.*;

class Solution {
    public int[][] cloneGraph(int[][] adj, int start) {
        int n = adj.length;
        int[] newId = new int[n];
        Arrays.fill(newId, -1);
        List<Integer> order = new ArrayList<>();
        newId[start] = 0;
        order.add(start);
        for (int h = 0; h < order.size(); h++) { // order doubles as the BFS queue
            int v = order.get(h);
            int[] nb = adj[v].clone();
            Arrays.sort(nb); // explore neighbours in increasing label
            for (int u : nb)
                if (newId[u] == -1) { newId[u] = order.size(); order.add(u); }
        }
        int[][] copy = new int[order.size()][];
        for (int i = 0; i < order.size(); i++) {
            int[] old = adj[order.get(i)];
            int[] row = new int[old.length];
            for (int j = 0; j < old.length; j++) row[j] = newId[old[j]]; // translate edge
            Arrays.sort(row);
            copy[i] = row;
        }
        return copy;
    }
}

