class Solution:
    def cloneGraph(self, adj: List[List[int]], start: int) -> List[List[int]]:
        new = {start: 0}; order = [start]; q = deque([start])
        while q:
            v = q.popleft()
            for u in sorted(adj[v]):
                if u not in new:
                    new[u] = len(order); order.append(u); q.append(u)
        return [sorted(new[u] for u in adj[v]) for v in order]

