function cloneGraph(adj, start) {
  const nw = new Map([[start, 0]]), order = [start];
  for (let h = 0; h < order.length; h++) {
    const v = order[h];
    for (const u of [...adj[v]].sort((a, b) => a - b)) if (!nw.has(u)) { nw.set(u, order.length); order.push(u); }
  }
  return order.map(v => adj[v].map(u => nw.get(u)).sort((a, b) => a - b));
}
